#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define INF 0x3f3f3f3f

typedef struct {
    int time;
    int u;
    int c;
} HeapNode;

HeapNode *heap;
int heap_size = 0;

void heap_push(int time, int u, int c) {
    int i = ++heap_size;
    while (i > 1 && heap[i / 2].time > time) {
        heap[i] = heap[i / 2];
        i /= 2;
    }
    heap[i].time = time;
    heap[i].u = u;
    heap[i].c = c;
}

HeapNode heap_pop(void) {
    HeapNode min = heap[1];
    HeapNode last = heap[heap_size--];
    int i = 1;
    while (1) {
        int child = i * 2;
        if (child > heap_size) break;
        if (child + 1 <= heap_size && heap[child + 1].time < heap[child].time)
            child++;
        if (last.time <= heap[child].time) break;
        heap[i] = heap[child];
        i = child;
    }
    heap[i] = last;
    return min;
}

int main(void) {
    int V, N, M;
    if (scanf("%d %d %d", &V, &N, &M) != 3) return 0;

    int *head = (int *)malloc((N + 1) * sizeof(int));
    for (int i = 0; i <= N; i++) head[i] = -1;

    int max_edges = 2 * M + 5;
    int *to = (int *)malloc(max_edges * sizeof(int));
    int *nxt = (int *)malloc(max_edges * sizeof(int));
    int *etime = (int *)malloc(max_edges * sizeof(int));
    int *ecost = (int *)malloc(max_edges * sizeof(int));
    int edge_cnt = 0;

    for (int i = 0; i < M; i++) {
        int A, B, T, P;
        scanf("%d %d %d %d", &A, &B, &T, &P);

        to[edge_cnt] = B;
        etime[edge_cnt] = T;
        ecost[edge_cnt] = P;
        nxt[edge_cnt] = head[A];
        head[A] = edge_cnt++;

        to[edge_cnt] = A;
        etime[edge_cnt] = T;
        ecost[edge_cnt] = P;
        nxt[edge_cnt] = head[B];
        head[B] = edge_cnt++;
    }

    int X, Y;
    scanf("%d %d", &X, &Y);

    int states = (N + 1) * (V + 1);
    int *dist = (int *)malloc(states * sizeof(int));
    memset(dist, 0x3f, states * sizeof(int));

    int heap_cap = (V + 1) * 2 * M + 5;
    heap = (HeapNode *)malloc(heap_cap * sizeof(HeapNode));
    heap_size = 0;

    int start_idx = X * (V + 1) + 0;
    dist[start_idx] = 0;
    heap_push(0, X, 0);

    while (heap_size > 0) {
        HeapNode cur = heap_pop();
        int u = cur.u;
        int c = cur.c;
        int t = cur.time;

        if (t != dist[u * (V + 1) + c]) continue;

        if (u == Y) {
            printf("%d\n", t);
            return 0;
        }

        for (int e = head[u]; e != -1; e = nxt[e]) {
            int v = to[e];
            int nc = c + ecost[e];
            if (nc > V) continue;

            int nt = t + etime[e];
            int idx = v * (V + 1) + nc;
            if (nt < dist[idx]) {
                dist[idx] = nt;
                heap_push(nt, v, nc);
            }
        }
    }

    printf("-1\n");
    return 0;
}
